<?php
declare(strict_types=1);
namespace EPejabat\Modules\EForms;
use EPejabat\Core\{Support,Core,Database};
final class PackageWeb {
 private static function e($v):string {return Support::escape((string)$v);}
 private static function form(string $action,string $body,string $button,bool $upload=false):string {return '<form method="post"'.($upload?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="'.$action.'">'.$body.'<button>'.$button.'</button></form>';}
 private static function orgs(\PDO $p,int $u,string $permission):array {$out=[];foreach($p->query('SELECT id,name FROM organisations WHERE is_active=1 ORDER BY name')->fetchAll() as $o){try{Service::permit($p,$u,$permission,(int)$o['id']);$out[]=$o;}catch(\RuntimeException $e){}}return $out;}
 public static function routes(\PDO $p,int $u):?string {
  if(!Packages::ready($p))return null;Core::module($p,'eforms');
  if($_SERVER['REQUEST_METHOD']==='POST'&&str_starts_with((string)($_POST['action']??''),'package_')){Support::checkCsrf();if($_POST['action']==='package_upload'){$token=Packages::stage($p,$u,Core::id($_POST['organisation_id']??null),$_FILES['package']??[]);Support::redirect('/eforms?packages=1&stage='.$token);}if($_POST['action']==='package_confirm'){if(($_POST['confirm']??'')!=='1')throw new \InvalidArgumentException('Pengesahan import diperlukan.');$id=Packages::confirm($p,$u,Support::post('stage',48),is_array($_POST['reviewers']??null)?$_POST['reviewers']:[]);Support::redirect('/eforms?studio='.$id);}throw new \InvalidArgumentException('Tindakan pakej tidak sah.');}
  if(isset($_GET['package_original'])){$r=Packages::staged($p,$u,Core::text($_GET['package_original'],48));header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="package-original.pdf"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: sandbox');echo $r['data']['pdf'];exit;}
  if(isset($_GET['packages']))return self::admin($p,$u);
  if(isset($_GET['library']))return self::library($p,$u);
  return null;
 }
 public static function admin(\PDO $p,int $u):string {
  $orgs=self::orgs($p,$u,'templates.manage');if(!$orgs)throw new \RuntimeException('Permission Admin borang diperlukan.');
  $h='<h2>Pusat Borang Digital — Import ZIP Borang</h2><p>Pakej borang mengandungi JSON dan PDF sahaja. Semakan hash bukan pengesahan publisher. Semak sumber PDF sebelum menerbitkan.</p><p><a href="/eforms?library=1">Perpustakaan Borang</a> · <a href="/eforms">Permohonan &amp; template</a></p>';
  if(isset($_GET['stage'])){$token=Core::text($_GET['stage'],48);$r=Packages::staged($p,$u,$token);$d=$r['data'];$org=(int)$r['stage']['organisation_id'];$state=Packages::conflict($p,$org,$d);$h.='<section class="card"><h3>'.self::e($d['manifest']['title']).'</h3><p>'.self::e($d['manifest']['description']).'</p><p>Integriti/format: PASS · '.self::e($state).'</p><p>Revision pakej '.(int)$d['manifest']['revision'].' · '.count($d['fields']).' medan · '.count($d['definition']['pages']).' halaman</p><a href="/eforms?package_original='.$token.'">Semak PDF asal</a><ul>';foreach($d['fields'] as $f)$h.='<li>'.self::e($f['label'].' — '.$f['type'].($f['required']?' (wajib)':'')).'</li>';$h.='</ul><p>Selepas import, gunakan Preview desktop/mobile dan peta PDF dalam Studio. Import tidak menerbitkan borang.</p>';
   if(!str_starts_with($state,'BLOCKED')){$people=[];foreach(Database::query($p,'SELECT u.id,s.full_name FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.is_active=1 ORDER BY s.full_name')->fetchAll() as $candidate){try{Service::permit($p,(int)$candidate['id'],'submissions.review',$org);$people[]=$candidate;}catch(\RuntimeException $e){}}
    $body='<input type="hidden" name="stage" value="'.$token.'">';foreach($d['steps'] as $i=>$s){$body.='<label>'.self::e(($i+1).'. '.$s['label'].' — '.$s['kind']).'<select name="reviewers[]" required><option value="">Pilih pegawai diberi kuasa</option>';foreach($people as $a)$body.='<option value="'.(int)$a['id'].'">'.self::e($a['full_name']).'</option>';$body.='</select></label>';}$body.='<label><input type="checkbox" name="confirm" value="1" required>Saya sahkan skop, sumber pakej dan pegawai. Import sebagai DRAFT sahaja.</label>';$h.=self::form('package_confirm',$body,'Sahkan import draf');}
   return $h.'</section>';
  }
  $body='<label>Organisasi pemilik<select name="organisation_id" required>';foreach($orgs as $o)$body.='<option value="'.(int)$o['id'].'">'.self::e($o['name']).'</option>';$body.='</select></label><label>ZIP borang (maksimum 12 MB)<input type="file" name="package" accept=".zip,application/zip" required></label>';return $h.self::form('package_upload',$body,'Upload & Validate',true);
 }
 public static function library(\PDO $p,int $u):string {
  $ids=array_column(self::orgs($p,$u,'submissions.create'),'id');$q=Core::text($_GET['q']??'',100,false);$page=max(1,min(10000,(int)($_GET['page']??1)));$h='<h2>Pusat Borang Digital</h2><p><a href="/eforms">Permohonan saya &amp; tracking</a> · <a href="/eforms?packages=1">Import ZIP Borang</a></p><form method="get"><input type="hidden" name="library" value="1"><label>Cari tajuk / kategori<input name="q" value="'.self::e($q).'" maxlength="100"></label><button>Cari</button></form>';
  if(!$ids)return $h.'<p>Tiada borang dalam permission dan skop anda.</p>';
  $sql="SELECT t.*,o.name AS owner,v.version,v.id AS version_id,vv.definition_json,(SELECT pi.description FROM eforms_package_imports pi JOIN eforms_package_forms pf ON pf.id=pi.package_form_id WHERE pf.template_id=t.id ORDER BY pi.id DESC LIMIT 1) AS description FROM eforms_templates t JOIN organisations o ON o.id=t.organisation_id JOIN eforms_versions v ON v.id=(SELECT MAX(v2.id) FROM eforms_versions v2 WHERE v2.template_id=t.id) LEFT JOIN eforms_visual_versions vv ON vv.version_id=v.id WHERE t.status='published' AND t.organisation_id IN (".implode(',',array_fill(0,count($ids),'?')).") AND (t.title LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(vv.definition_json,'$.category')) LIKE ?) ORDER BY t.title,t.id LIMIT 25 OFFSET ".(($page-1)*25);
  $rows=Database::query($p,$sql,[...$ids,'%'.$q.'%','%'.$q.'%'])->fetchAll();foreach($rows as $r){$d=json_decode($r['definition_json']?:'{}',true);$date=$d['effective_date']??'';$available=!$date||$date<=gmdate('Y-m-d');$h.='<section class="card"><h3>'.self::e($r['title']).'</h3><p>'.self::e($r['description']??'').'</p><p>'.self::e(($d['category']??'').' · '.$r['owner']).'</p><p>Revision '.(int)$r['version'].' · '.self::e($date?:'Berkuat kuasa sekarang').' · '.($available?'Tersedia':'Belum berkuat kuasa').'</p>';if($available)$h.=self::form('new','<input type="hidden" name="id" value="'.(int)$r['id'].'">','Mula permohonan');$h.='</section>';}
  if(!$rows)$h.='<p>Tiada borang ditemui.</p>';if($page>1)$h.='<a href="/eforms?'.self::e(http_build_query(['library'=>1,'q'=>$q,'page'=>$page-1])).'">Sebelum</a> ';if(count($rows)===25)$h.='<a href="/eforms?'.self::e(http_build_query(['library'=>1,'q'=>$q,'page'=>$page+1])).'">Seterusnya</a>';return $h;
 }
}
